// CSD_RATIONALE_BEGIN
// Root cause analysis of attempt 35:
// 15/49 unterminated spans — the 8-token warmup caused dead-ends; remaining
// budget was then too thin for CloseSpanWithinBudget.
// 30/49 wrong answers — ConstrainedStep + CloseSpanIfComplete closes at the
// FIRST complete arithmetic expression (e.g., "n1" or "n1 + n2") rather than
// the intended full formula like "n1 + n1 * mult + n2 + n3".
//
// Fix: Replace ConstrainedStep + CloseSpanIfComplete with CloseSpanWithinBudget,
// which tracks the LONGEST complete prefix found while generating forward.
// This prevents premature closure: the model generates "n1 + n1 * mult + n2 + n3"
// and CloseSpanWithinBudget captures that full expression, not just "n1".
//
// Strategy:
//   Phase 1: Free generation (70% budget) watching for natural "<<"
//   Phase 2: CloseSpanWithinBudget with ALL remaining budget
//   Phase 3: If no span opened, force open + CloseSpanWithinBudget for rest
//
// No warmup loop (avoids dead-end budget waste from attempt 35).
// No inner ConstrainedStep loop (avoids premature closure from all prior attempts).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedStep loop): insideConstrainedOut stays false in the
//     loop body (guard !insideConstrainedOut). On EOS we break. On "<<",
//     EnterObservedConstrainedSpan sets currentConstrainedOut := [] and
//     parser.IsValidPrefix([]) holds by method precondition; loop exits on next
//     guard check. So the invariant is vacuously true inside the loop and holds
//     on entry to Phase 2.  ✓
//
//   Phase 2 (CloseSpanWithinBudget): library postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut).  ✓
//
//   Phase 3 (OpenConstrainedSpan): sets currentConstrainedOut := [], which
//     satisfies IsValidPrefix([]) by precondition. Subsequent CloseSpanWithinBudget
//     maintains the invariant by its own postcondition.  ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Phase 1: each UnconstrainedStep costs +1 step and appends at most 1 visible
//     token (EOS appends 0). EnterObservedConstrainedSpan appends 0 tokens and
//     costs 0 steps. So per iteration |generated| grows by at most 1 = delta(steps). ✓
//
//   Phase 2: CloseSpanWithinBudget postcondition gives
//     |generatedOut| <= |generated_entry| + bud. Setting steps := steps + bud
//     gives |generated| <= |generatedPrefix| + steps_ph1 + bud
//     = |generatedPrefix| + maxSteps.  ✓
//
//   Phase 3 open: OpenConstrainedSpan appends "<<" (1 token), steps += 1.
//     |generated| <= |generatedPrefix| + steps_ph1 + 1 = |generatedPrefix| + steps_after_open. ✓
//     CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| + bud2.
//     Total: |generated| <= |generatedPrefix| + steps_after_open + bud2
//     = |generatedPrefix| + steps_after_open + (maxSteps - steps_after_open)
//     = |generatedPrefix| + maxSteps.  ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Write the final answer as: The answer is EXPR. " +
  "EXPR must be a complete arithmetic expression combining ALL relevant variables from the problem. " +
  "Variable names: copy exactly from the problem text, removing the braces. " +
  "Allowed: variable names, numbers, +, -, *, /, (, ), int(). No LaTeX, no dollar signs. " +
  "Use int() when multiplying by a fraction: int(n * frac). " +
  "When the problem says 'mult times n1', write n1 * mult, not just mult. " +
  "Examples: n * bill - (m * p1 + k * p2), int(n1 * frac1 + n2 * frac2 - spill * frac1), (n1 + n1 * mult + n2 + n3).");

var steps: nat := 0;

// Phase 1 budget: 70% of maxSteps for unconstrained reasoning
var phase1Budget: nat := 0;
if maxSteps >= 2 {
  phase1Budget := (maxSteps * 7) / 10;
} else {
  phase1Budget := maxSteps;
}

// Phase 1: Free generation watching for natural "<<"
while steps < phase1Budget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Budget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken { break; }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
  }
}

// Phase 2: Close span with ALL remaining budget (longest-complete-prefix semantics)
if insideConstrainedOut && steps < maxSteps {
  var bud := maxSteps - steps;
  var wg, wi, wc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud
  );
  generated := wg;
  insideConstrainedOut := wi;
  currentConstrainedOut := wc;
  steps := steps + bud;
}

// Phase 3: If no span opened, force one open and close with remaining budget
if !insideConstrainedOut && steps + 1 < maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg;
  insideConstrainedOut := fi;
  currentConstrainedOut := fc;
  steps := steps + 1;

  if steps < maxSteps {
    var bud2 := maxSteps - steps;
    var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud2
    );
    generated := wg2;
    insideConstrainedOut := wi2;
    currentConstrainedOut := wc2;
    steps := steps + bud2;
  }
}

cost := steps;

